                    Task_LanguageSelectActivity.this.editor.putBoolean(Task_LanguageSelectActivity.this.str, true);
                    Task_LanguageSelectActivity.this.progressDialog = new ProgressDialog(Task_LanguageSelectActivity.this);
                    Task_LanguageSelectActivity.this.progressDialog.setMessage("Loading...");
                    Task_LanguageSelectActivity.this.progressDialog.setTitle("please wait Fetching Data...");
                    Task_LanguageSelectActivity.this.progressDialog.setProgressStyle(0);
                    Task_LanguageSelectActivity.this.progressDialog.show();
                    Task_LanguageSelectActivity.this.progressDialog.setCancelable(false);
